CREATE procedure ILD_DIY_MacDinh_BatchSSCC_Bin_Issue_OLD
(
	in itemCode nvarchar(50),
	in WhsCode nvarchar(50),
	in qtyNeedIssue decimal(19,6)
)
As
Begin

		--declare itemCode nvarchar(50) = '1520100002';
		--declare WhsCode nvarchar(50) = 'AA';
		--declare qtyNeedIssue decimal(19,6) = 10;
--1. Lấy danh sách Item - Batch  - số lượng - hiện co (tham số truyền vào là itemcode, kho)
		create local temporary table #SSCC_Batch_QtyAvalible
		(
			RowNum 	int ,
			--generated by default as identity(start with 1 increment by 1) not null,
			ItemCode nvarchar(50),
			Batch nvarchar(50),
			SSCC nvarchar(50),
			Qty_Avalible decimal(19,6),
			ExpDate date,
			MnfDate date,
			AbsEntry	int,
			-- Thong tin Bin
			BinCode nvarchar(100),
			Qty_UuTien decimal(19,6)
			
			
		);
		
		insert into #SSCC_Batch_QtyAvalible (RowNum,
											 ItemCode,Batch,SSCC,Qty_Avalible, ExpDate, MnfDate ,AbsEntry,
											BinCode,
											Qty_UuTien
											)
		
		select  ROW_NUMBER() OVER (order by ifnull(b."ExpDate", b."MnfDate")) ,
				:itemCode,b."MnfSerial" as  "Batch",b."DistNumber" as "SSCC", a."Quantity",
				b."ExpDate",b."MnfDate",
				b."AbsEntry",
				d."BinCode",
				a."Quantity" - :qtyNeedIssue
		from OBTQ a
		inner join OBTN b on a."MdAbsEntry"  =  b."AbsEntry"
		inner join OBBQ c on c."SnBMDAbs"  =   b."AbsEntry" and c."ItemCode" = :itemCode and c."WhsCode"  = :WhsCode
		inner join OBIN d on c."BinAbs" = d."AbsEntry"
		where 
		 a."Quantity"  > 0  and a."ItemCode"  =  :itemCode and a."WhsCode"  = :WhsCode;
		 
---
/*
các trường hợp: 
1. Qty_UuTien (dong đầu tiên - top 1) >0 thì lây top 1
Trường hợp 2:
2. Qty_UuTien (dong đầu tiên - top 1) < 0 thì: số lượng yêu cầu xuất > số lượng dòng đầu --> Duyệt for sum đến tổng số lương > số lượng request

*/
		
		IF exists(select Qty_UuTien from #SSCC_Batch_QtyAvalible where RowNum  =  1 and Qty_UuTien >0 order by  ifnull(ExpDate, MnfDate) ) then
			Begin
			 
			 If(select Qty_Avalible from #SSCC_Batch_QtyAvalible where RowNum  = 1)> qtyNeedIssue then
			 	update a
			 	set Qty_Avalible  = qtyNeedIssue
			 	from #SSCC_Batch_QtyAvalible a
			 	where RowNum = 1;
			 End If;
		 	 select top 1 * from #SSCC_Batch_QtyAvalible where RowNum =1;
		
			End;
		Else 
			Begin
				Declare i int = 1;
				Declare loopCount int = 0;
				Declare qtySumRow int = 0;
				
				Select Count(*) Into loopCount From #SSCC_Batch_QtyAvalible;
		       		While :i <= :loopCount
		       			DO
		       				Begin      					
		       					
		       					qtySumRow = qtySumRow +   (select Qty_Avalible from  #SSCC_Batch_QtyAvalible where RowNum  = :i);  					
									       					
		       					i := i + 1;
		       				End;
		       				If(qtySumRow>=qtyNeedIssue) then -- Soo luong trong kho >= so luon yeu cau
		       					delete 
		       					from #SSCC_Batch_QtyAvalible where RowNum >= i;
		       					
		       					IF(qtySumRow>qtyNeedIssue) then
		       
						      	 update a
						      	 set  Qty_Avalible  = (select sum (Qty_Avalible) from #SSCC_Batch_QtyAvalible where RowNum =:i-1) - ((select sum (Qty_Avalible) from #SSCC_Batch_QtyAvalible) - qtyNeedIssue)
						      	 from #SSCC_Batch_QtyAvalible a
						      	 where RowNum= i-1;
						      	 
						      	 
						       End IF;
						       					
		       					
		       					
		       					select *  from #SSCC_Batch_QtyAvalible;
		       					
		       					BREAK;
		       				Else
		       					select *  from #SSCC_Batch_QtyAvalible;
		       					
		       					BREAK;
		       				End if;
		       				
		       		End While;
		       
			End;
		
		
		End IF;
		 
		
		
		
	drop table #SSCC_Batch_QtyAvalible;


End;

